-- Places employers' postings name, decided by the data: data/employers/places.json,
-- generated by scripts/build-posting-places-sql.mjs. Edit the JSON and regenerate; do not edit this file by hand.
-- A place is pointed at the plant it is, or left (not a plant), as Admin Tools would; a person's decision is never changed.
-- posting_decide takes one rule more (scripts/posting-decide.sql), and the jobs are brought in line with the data.
-- What it decided is in load_log (load 'posting-places'; the lines with look = true are the ones to read).
-- Safe to run again: a place already decided so is left as it is, and nothing is written.

-- posting_decide (migration 0054) as it stands from migration 0067: the same
-- function, with two rules more for the near rule (the company's nearest plant
-- within 10 km of a town where it has none). A place set aside as no plant, by a
-- person in Admin Tools or by the data (data/employers/places.json), takes no
-- plant by it. And a posting another of whose places has its plant (by the city,
-- or pointed) takes no second job by it. Read into 0067 and 0079 by
-- scripts/build-posting-places-sql.mjs; a change to it is a change here and a new
-- generated migration. The place a caller asks about (`p_place`) narrows only
-- the answer: every place of a posting is weighed, so one place asked about
-- alone is decided as it is with the rest.

-- For every staged posting of a source that is still on the employer's site,
-- at every place it names: the plant it is at and the career it is. One row
-- per posting and place; factory_id is null where no plant could be found
-- (the place waits) and occupation_id where the career is not stored.
--
-- The plant, in this order (`how`):
--   admin    the place was pointed at a plant, by an admin or by the data (posting_places.status 'pointed')
--   city     the company's one plant in that city and state
--   address  of several there, the one whose street address the posting's words carry
--   name     ... or whose name they carry (the words of the plant's name that are not the company's, the city's or generic)
--   largest  ... else the one with the most people
--   keeps    ... none of them with a headcount: the one the plant merge would keep of them (plant_keeps' order:
--            written from sources, then placed in a county, then more facts filled in, then the older, then the
--            lower id). The same plant every run; marked for a look
--   near     none in the city: the company's nearest plant in the state within 10 km of the city's centre,
--            the centre being the middle of every plant we list in that city (no outside geocoder); never
--            for a place set aside as no plant (posting_places.status 'left'), and never for a posting
--            another of whose places has its plant
-- "The company" is posting_companies. The posting's words are what staging
-- keeps of it: its title, its location line, its street address, its department.
-- `options` is how many plants were candidates; `metres` the distance for 'near'.
CREATE OR REPLACE FUNCTION posting_decide(p_source text, p_place text DEFAULT NULL)
RETURNS TABLE (source_id text, place_key text, city text, state text, company_id uuid, factory_id uuid, occupation_id uuid,
               how text, metres integer, options integer)
LANGUAGE sql STABLE AS $f$
  WITH fam AS (
    SELECT company_id FROM posting_companies(p_source)
  ), rec AS (
    SELECT r.source_id, r.facts,
           posting_words(concat_ws(' ', r.facts->>'title', r.facts->>'location', r.facts->>'address', r.facts->>'department')) AS words,
           (SELECT o.id FROM occupations o WHERE lower(o.title) = lower(r.facts->'reading'->'career'->>'title') ORDER BY o.id LIMIT 1) AS occupation_id
    FROM intake_records r
    WHERE r.source = p_source AND r.gone_run_id IS NULL
  ), rp AS (
    SELECT DISTINCT ON (rec.source_id, k.place_key)
           rec.source_id, rec.words, rec.occupation_id, k.place_key, k.city_key, btrim(p->>'city') AS city, upper(btrim(p->>'state')) AS state
    FROM rec
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(rec.facts->'reading'->'places') = 'array' THEN rec.facts->'reading'->'places' ELSE '[]'::jsonb END) p
    CROSS JOIN LATERAL (SELECT posting_city_key(p->>'city') AS city_key, posting_place_key(p->>'city', p->>'state') AS place_key) k
    WHERE k.city_key <> '' AND upper(btrim(coalesce(p->>'state', ''))) ~ '^[A-Z]{2}$'
    ORDER BY rec.source_id, k.place_key
  ), ours AS (
    SELECT f.id, f.company_id, f.state, posting_city_key(f.city) AS city_key, f.workforce_size, f.curated, f.created_at, f.lat, f.lng,
           (f.county_fips IS NOT NULL) AS in_county,
           -- How many facts are filled in, counted as plant_keeps counts them.
           ((NULLIF(btrim(f.address), '') IS NOT NULL)::int + (NULLIF(btrim(f.city), '') IS NOT NULL)::int
            + (NULLIF(btrim(f.zip_code), '') IS NOT NULL)::int + (f.primary_naics IS NOT NULL)::int
            + (f.primary_naics_description IS NOT NULL)::int + (NULLIF(btrim(f.products), '') IS NOT NULL)::int
            + (f.opened_year IS NOT NULL)::int) AS facts,
           -- The street number and the first word of the street: "12100 samsung".
           (regexp_match(posting_words(f.address), '^ ([0-9]{2,6}) ([a-z0-9]+) '))[1:2] AS street,
           -- The words of its name that tell it from the company's other plants.
           ARRAY(SELECT DISTINCT w FROM regexp_split_to_table(btrim(posting_words(f.name)), ' ') w
                 WHERE (length(w) >= 4 OR (w ~ '[0-9]' AND length(w) >= 2))
                   AND position(' ' || w || ' ' IN posting_words(co.name || ' ' || coalesce(f.city, '') || ' ' || coalesce(f.state, ''))) = 0
                   AND w NOT IN ('plant', 'plants', 'factory', 'facility', 'facilities', 'manufacturing', 'operations', 'operation', 'division',
                                 'company', 'corporation', 'corp', 'incorporated', 'site', 'center', 'centre', 'campus', 'building', 'bldg',
                                 'works', 'north', 'south', 'east', 'west', 'america', 'american', 'usa', 'international', 'industries',
                                 'products', 'systems', 'group', 'holdings', 'technologies', 'technology', 'services', 'assembly',
                                 'space', 'exploration', 'development', 'engineering', 'research', 'global', 'general', 'national', 'united')) AS telling
    FROM factories f JOIN companies co ON co.id = f.company_id
    WHERE f.company_id IN (SELECT company_id FROM fam)
  ), pointed AS (
    SELECT pp.place_key, f.id, f.company_id
    FROM posting_places pp JOIN factories f ON f.id = record_now('factory', pp.factory_id)
    WHERE pp.source = p_source AND pp.status = 'pointed' AND pp.factory_id IS NOT NULL
  ), incity AS (
    SELECT rp.source_id, rp.place_key, o.id, o.company_id, o.workforce_size, o.curated, o.created_at, o.in_county, o.facts,
           CASE WHEN o.street IS NOT NULL AND position(' ' || o.street[1] || ' ' || o.street[2] || ' ' IN rp.words) > 0 THEN 100 ELSE 0 END
             + (SELECT count(*) FROM unnest(o.telling) w WHERE position(' ' || w || ' ' IN rp.words) > 0)::integer AS fit
    FROM rp JOIN ours o ON o.state = rp.state AND o.city_key = rp.city_key
    WHERE NOT EXISTS (SELECT 1 FROM pointed a WHERE a.place_key = rp.place_key)
  ), ranked AS (
    SELECT c.*, count(*) OVER w AS options,
           -- The posting's words first, then the most people; where neither chooses, the plant merge's own order.
           row_number() OVER (w ORDER BY c.fit DESC, c.workforce_size DESC NULLS LAST,
                                         c.curated DESC, c.in_county DESC, c.facts DESC, c.created_at, c.id) AS pick,
           count(*) FILTER (WHERE c.fit = m.best) OVER w AS at_best, m.best
    FROM incity c
    JOIN (SELECT source_id, place_key, max(fit) AS best FROM incity GROUP BY 1, 2) m ON m.source_id = c.source_id AND m.place_key = c.place_key
    WINDOW w AS (PARTITION BY c.source_id, c.place_key)
  ), empty_places AS (
    -- Places where the company has no plant in the city and no admin has pointed: the city's centre, from every plant we list there.
    SELECT pl.place_key, pl.state, c.lat, c.lng
    FROM (SELECT DISTINCT rp.place_key, rp.city_key, rp.state FROM rp
          WHERE NOT EXISTS (SELECT 1 FROM pointed a WHERE a.place_key = rp.place_key)
            AND NOT EXISTS (SELECT 1 FROM ours o WHERE o.state = rp.state AND o.city_key = rp.city_key)
            -- A place set aside as no plant (by a person or by the data) is not given the nearest plant: a posting for an
            -- office is not shown at a factory 10 km off. A plant of the company in the city itself still wins.
            AND NOT EXISTS (SELECT 1 FROM posting_places x WHERE x.source = p_source AND x.place_key = rp.place_key AND x.status = 'left')) pl
    CROSS JOIN LATERAL (
      SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY f.lat) AS lat, percentile_cont(0.5) WITHIN GROUP (ORDER BY f.lng) AS lng
      FROM factories f WHERE f.state = pl.state AND f.lat IS NOT NULL AND f.lng IS NOT NULL AND posting_city_key(f.city) = pl.city_key
    ) c
    WHERE c.lat IS NOT NULL
  ), near AS (
    SELECT DISTINCT ON (e.place_key) e.place_key, o.id, o.company_id, posting_metres(e.lat, e.lng, o.lat::float8, o.lng::float8) AS metres,
           count(*) OVER (PARTITION BY e.place_key)::integer AS options
    FROM empty_places e JOIN ours o ON o.state = e.state AND o.lat IS NOT NULL AND o.lng IS NOT NULL
    WHERE posting_metres(e.lat, e.lng, o.lat::float8, o.lng::float8) <= 10000
    ORDER BY e.place_key, posting_metres(e.lat, e.lng, o.lat::float8, o.lng::float8), o.id
  ), decided AS (
    SELECT rp.source_id, rp.place_key, rp.city, rp.state,
           coalesce(a.company_id, r.company_id, n.company_id) AS company_id,
           coalesce(a.id, r.id, n.id) AS factory_id,
           rp.occupation_id,
           CASE WHEN a.id IS NOT NULL THEN 'admin'
                WHEN r.id IS NOT NULL THEN CASE WHEN r.options = 1 THEN 'city'
                                                WHEN r.best >= 100 AND r.at_best = 1 THEN 'address'
                                                WHEN r.best > 0 AND r.at_best = 1 THEN 'name'
                                                WHEN r.workforce_size IS NOT NULL THEN 'largest'
                                                ELSE 'keeps' END
                WHEN n.id IS NOT NULL THEN 'near' END AS how,
           n.metres,
           coalesce(r.options, n.options, 0)::integer AS options
    FROM rp
    LEFT JOIN pointed a ON a.place_key = rp.place_key
    LEFT JOIN ranked r ON r.source_id = rp.source_id AND r.place_key = rp.place_key AND r.pick = 1
    LEFT JOIN near n ON n.place_key = rp.place_key AND a.id IS NULL AND r.id IS NULL
  )
  -- One posting is one job at a plant. Where two of the places it names come to the same plant (the plant's own
  -- city and a town beside it, or a place an admin pointed there), the place that is the plant's by rule stands
  -- and the other makes nothing: not a second job, and not a place that waits. And the near rule is a fallback for
  -- a posting that has no plant otherwise: where another place it names has its plant (by the city, or pointed), a
  -- town beside it makes nothing either, not a second job at whatever plant stands nearest that town.
  SELECT d.source_id, d.place_key, d.city, d.state, d.company_id, d.factory_id, d.occupation_id, d.how, d.metres, d.options
  FROM (SELECT decided.*,
               row_number() OVER (PARTITION BY decided.source_id, decided.factory_id
                                  ORDER BY (decided.how = 'near'), (decided.how = 'admin'), decided.metres NULLS FIRST, decided.place_key) AS nth,
               bool_or(decided.factory_id IS NOT NULL AND decided.how <> 'near') OVER (PARTITION BY decided.source_id) AS placed_otherwise
        FROM decided) d
  WHERE (d.factory_id IS NULL OR (d.nth = 1 AND NOT (d.how = 'near' AND d.placed_otherwise)))
    -- `p_place` (one place, as Admin Tools and 0067 apply it) narrows the answer, never what is weighed: a posting's
    -- other places still decide whether this one is its plant's by rule.
    AND (p_place IS NULL OR d.place_key = p_place)
$f$;

-- One line in load_log. A line marked once is written only when the same line is not there yet, so a run that finds
-- nothing to do writes nothing.
CREATE OR REPLACE FUNCTION pg_temp.pp_log(p_action text, p_look boolean, p_company text, p_plant text, p_detail text, p_source text, p_id uuid, p_once boolean)
RETURNS void LANGUAGE sql AS $f$
  INSERT INTO load_log (load, kind, action, look, company, plant, detail, source_id, entity_id)
  SELECT 'posting-places', 'place', p_action, p_look, p_company, p_plant, p_detail, p_source, p_id
  WHERE NOT p_once OR NOT EXISTS (
    SELECT 1 FROM load_log l WHERE l.load = 'posting-places' AND l.action = p_action AND l.source_id IS NOT DISTINCT FROM p_source
      AND l.detail IS NOT DISTINCT FROM p_detail)
$f$;

-- Whether a person has decided this place in Admin Tools: pointed it, left it, or took a decision back (a decision too).
-- The audit line is the mark: Admin Tools writes one for each, with the person, the employer and the place.
CREATE OR REPLACE FUNCTION pg_temp.pp_person_decided(p_employer text, p_where text) RETURNS boolean LANGUAGE sql STABLE AS $f$
  SELECT EXISTS (
    SELECT 1 FROM audit_log a
    WHERE a.kind IN ('factory', 'company')
      AND a.action IN ('postings pointed here', 'postings place left', 'postings place waits again')
      AND (a.actor_id IS NOT NULL OR btrim(a.actor_name) <> '')
      AND lower(a.detail->>'place') = lower(p_where)
      AND lower(a.detail->>'employer') = lower(p_employer))
$f$;

-- The employers' sources, for a database whose runner has not met them yet: written as the runner writes them, and an
-- existing one is never changed.
CREATE OR REPLACE FUNCTION pg_temp.pp_sources(data jsonb) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  s jsonb;
BEGIN
  FOR s IN SELECT x FROM jsonb_array_elements(data->'sources') x LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM intake_sources WHERE slug = s->>'slug');
    INSERT INTO intake_sources (slug, name, publisher, url, terms, how_fetched, kind, ref_source, scope, unmatched, fill, rank, ranks, system, company, also)
      VALUES (s->>'slug', s->>'name', s->>'publisher', s->>'url', s->>'terms', s->>'how_fetched', s->>'kind', s->>'ref_source', s->>'scope',
              s->>'unmatched', s->>'fill', (s->>'rank')::smallint, '{}'::jsonb, s->>'system', s->>'company',
              CASE WHEN jsonb_typeof(s->'also') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(s->'also')) END)
      ON CONFLICT (slug) DO NOTHING;
    PERFORM pg_temp.pp_log('source registered', false, s->>'company', NULL,
      'the employer''s postings had not been run on this database: its source is written as the runner writes it, so its places are decided',
      s->>'slug', NULL, true);
  END LOOP;
END $f$;

CREATE OR REPLACE FUNCTION pg_temp.pp_decide(data jsonb) RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  p jsonb;
  v_key text;
  v_where text;
  r posting_places%ROWTYPE;
  v_plant uuid;
  v_name text;
  v_found integer;
  v_company record;
  v_written integer;
BEGIN
  PERFORM set_config('client_min_messages', 'warning', true);
  FOR p IN SELECT x FROM jsonb_array_elements(data->'places') x LOOP
    v_key := posting_place_key(p->>'city', p->>'state');
    v_where := format('%s, %s', p->>'city', p->>'state');
    IF NOT EXISTS (SELECT 1 FROM intake_sources WHERE slug = p->>'source') THEN
      PERFORM pg_temp.pp_log('no source', true, p->>'employer', NULL,
        format('%s: the employer has no source here: nothing written', v_where), p->>'source', NULL, true);
      CONTINUE;
    END IF;
    SELECT * INTO r FROM posting_places WHERE source = p->>'source' AND place_key = v_key;
    IF r.decided_by IS NOT NULL OR pg_temp.pp_person_decided(p->>'employer', v_where) THEN
      PERFORM pg_temp.pp_log('left as a person decided', false, p->>'employer', NULL,
        format('%s: %s in Admin Tools; the file would have it %s', v_where, coalesce(r.status, 'decided'), CASE WHEN p->>'decision' = 'point' THEN 'pointed' ELSE 'left' END),
        p->>'source', r.factory_id, true);
      CONTINUE;
    END IF;

    IF p->>'decision' = 'point' THEN
      -- The plant, by its company and exact name, among the employer's own companies (posting_companies) and in the place's state.
      SELECT count(*), min(f.id::text)::uuid, min(f.name) INTO v_found, v_plant, v_name
      FROM factories f JOIN companies c ON c.id = f.company_id
      WHERE (lower(c.name) = lower(p->>'company') OR EXISTS (SELECT 1 FROM unnest(c.aliases) a WHERE lower(a) = lower(p->>'company')))
        AND c.id IN (SELECT company_id FROM posting_companies(p->>'source'))
        AND lower(f.name) = lower(p->>'plant')
        AND (p->>'plantCity' IS NULL OR posting_city_key(f.city) = posting_city_key(p->>'plantCity'))
        AND f.state = p->>'state';
      IF v_found <> 1 THEN
        PERFORM pg_temp.pp_log('plant not found', true, p->>'company', p->>'plant',
          format('%s: %s plants of "%s" in %s are named so%s; the place is left waiting', v_where, v_found, p->>'company', p->>'state',
                 coalesce(' in ' || (p->>'plantCity'), '')), p->>'source', NULL, true);
        CONTINUE;
      END IF;
      CONTINUE WHEN r.status = 'pointed' AND record_now('factory', r.factory_id) = v_plant;
      INSERT INTO posting_places (source, place_key, city, state, status, factory_id, decided_at, decided_by)
        VALUES (p->>'source', v_key, p->>'city', p->>'state', 'pointed', v_plant, now(), NULL)
      ON CONFLICT (source, place_key) DO UPDATE SET status = 'pointed', factory_id = EXCLUDED.factory_id, decided_at = now(), decided_by = NULL
        WHERE posting_places.decided_by IS NULL;
      GET DIAGNOSTICS v_written = ROW_COUNT;
      CONTINUE WHEN v_written = 0;
      PERFORM pg_temp.pp_log('pointed', false, p->>'company', v_name, format('%s is this plant: its postings are jobs here', v_where), p->>'source', v_plant, false);
      INSERT INTO audit_log (actor_id, actor_name, kind, record_id, record_name, action, detail)
        VALUES (NULL, '', 'factory', v_plant, v_name, 'postings pointed here', jsonb_build_object('employer', p->>'employer', 'place', v_where));
    ELSE
      CONTINUE WHEN r.status = 'left';
      INSERT INTO posting_places (source, place_key, city, state, status, factory_id, decided_at, decided_by)
        VALUES (p->>'source', v_key, p->>'city', p->>'state', 'left', NULL, now(), NULL)
      ON CONFLICT (source, place_key) DO UPDATE SET status = 'left', factory_id = NULL, decided_at = now(), decided_by = NULL
        WHERE posting_places.decided_by IS NULL;
      GET DIAGNOSTICS v_written = ROW_COUNT;
      CONTINUE WHEN v_written = 0;
      PERFORM pg_temp.pp_log('left', false, p->>'employer', NULL, format('%s is not a plant: %s', v_where, p->>'kind'), p->>'source', NULL, false);
      SELECT c.id, c.name INTO v_company FROM companies c JOIN posting_companies(p->>'source') pc ON pc.company_id = c.id AND pc.named ORDER BY c.name LIMIT 1;
      INSERT INTO audit_log (actor_id, actor_name, kind, record_id, record_name, action, detail)
        VALUES (NULL, '', 'company', v_company.id, coalesce(v_company.name, p->>'employer'), 'postings place left',
                jsonb_build_object('employer', p->>'employer', 'place', v_where, 'kind', p->>'kind'));
    END IF;
  END LOOP;
END $f$;

-- The jobs, in line with the data as it now stands (the plants 0065 added, the rows 0066 moved, the places above), for
-- every employer with an applied run: what Admin Tools does when a person points a place, journalled under that run.
-- The waiting list is resolved first; then each place whose postings would be placed otherwise than their jobs are
-- (no job yet, or the job on another plant) is applied, which closes nothing. A job that is left on a plant that is
-- not the employer's is said with look: the next run closes or moves it.
CREATE OR REPLACE FUNCTION pg_temp.pp_jobs() RETURNS void LANGUAGE plpgsql AS $f$
DECLARE
  s record;
  v_place text;
  v_ref text;
  v_places integer;
  v_left integer;
  v_got jsonb;
  n_added integer;
  n_changed integer;
BEGIN
  FOR s IN SELECT r.source, max(r.id) AS run FROM intake_runs r JOIN intake_sources x ON x.slug = r.source AND x.kind = 'job'
           WHERE r.state = 'applied' GROUP BY r.source ORDER BY r.source LOOP
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM posting_companies(s.source) WHERE named);
    -- posting_resolve leaves what posting_decide says of every posting in posting_decided: the plan to compare with.
    PERFORM posting_resolve(s.source, s.run);
    SELECT ref_source INTO v_ref FROM intake_sources WHERE slug = s.source;
    v_places := 0; n_added := 0; n_changed := 0;
    FOR v_place IN
      SELECT DISTINCT d.place_key FROM posting_decided d
      LEFT JOIN external_references x ON x.source = v_ref AND x.entity_type = 'jobs' AND NOT x.duplicate AND x.external_id = d.source_id || '@' || d.place_key
      LEFT JOIN jobs j ON j.id = x.entity_id
      WHERE d.factory_id IS NOT NULL AND d.occupation_id IS NOT NULL
        AND (j.id IS NULL OR j.factory_id IS DISTINCT FROM d.factory_id OR j.company_id IS DISTINCT FROM d.company_id
             -- A job a run closed for want of a plant, whose posting the data now places: opened again, as the run would.
             OR (j.status <> 'open' AND j.closed_reason = 'No longer on the company''s careers site'))
      ORDER BY 1
    LOOP
      v_got := posting_apply(s.source, s.run, v_place);
      n_added := n_added + (v_got->>'added')::integer;
      n_changed := n_changed + (v_got->>'changed')::integer + (v_got->>'reopened')::integer;
      v_places := v_places + 1;
    END LOOP;
    IF v_places > 0 THEN
      PERFORM pg_temp.pp_log('jobs in line', false, (SELECT company FROM intake_sources WHERE slug = s.source), NULL,
        format('%s %s, under run %s: %s %s added, %s moved or opened again', v_places, CASE WHEN v_places = 1 THEN 'place' ELSE 'places' END,
               s.run, n_added, CASE WHEN n_added = 1 THEN 'job' ELSE 'jobs' END, n_changed), s.source, NULL, false);
    END IF;
    SELECT count(*) INTO v_left FROM jobs j JOIN factories f ON f.id = j.factory_id
      WHERE j.source = s.source AND j.status = 'open' AND f.company_id NOT IN (SELECT company_id FROM posting_companies(s.source));
    IF v_left > 0 THEN
      PERFORM pg_temp.pp_log('jobs on another firm''s plant', true, (SELECT company FROM intake_sources WHERE slug = s.source), NULL,
        format('%s open %s on a plant that is not the employer''s now: the next run closes or moves %s', v_left,
               CASE WHEN v_left = 1 THEN 'job is' ELSE 'jobs are' END, CASE WHEN v_left = 1 THEN 'it' ELSE 'them' END), s.source, NULL, true);
    END IF;
  END LOOP;
END $f$;

